                elif key == 'depen':
                    alt_pattern = r'Dependently Immutable Fields[^\d]*(\d+)'
                elif key == 'trans':
                    alt_pattern = r'Transitively Immutable Fields[^\d]*(\d+)'

                alt_match = re.search(alt_pattern, section)
                if alt_match:
                    algo_data[key] = format_number(alt_match.group(1))
                else:
                    # If still not found, set to placeholder
                    algo_data[key] = '??'

        results[algo] = algo_data

    return results

def generate_table(results):
    table = """**Table 4: Field Immutability Results for OpenJDK**

| Algorithm  | mutable | ⊒ non-trans. | ⊒ depen. | ⊒ trans. |
| ---------- | ------: | -----------: | -------: | -------: |\n"""

    algo_display = {
        'AdHocCHA': 'Ad-hoc CHA',
        'CHA': 'CHA',
        'RTA': 'RTA',
        'XTA': 'XTA'
    }

    # Order as in expected table
    for algo_key in ['AdHocCHA', 'CHA', 'RTA', 'XTA']:
        if algo_key in results:
            data = results[algo_key]
            # Ensure all fields are present, use placeholder if missing
            mutable = data.get('mutable', '?? ???')
            non_trans = data.get('non_trans', '?? ???')
            depen = data.get('depen', '???')
            trans = data.get('trans', '?? ???')
            table += f"| {algo_display[algo_key]} | {mutable} | {non_trans} | {depen} | {trans} |\n"

    table += "\n*depen. = dependently immutable, trans. = transitively immutable. Higher numbers in columns to the right = more precise.*"

    return table

